import React from "react";
import { motion } from "framer-motion";

const Hero = () => {
  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2,
        delayChildren: 0.1,
      },
    },
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: {
      opacity: 1,
      y: 0,
      transition: { duration: 0.8, ease: "easeOut" },
    },
  };

  return (
    <motion.section
      className="hero"
      id="top"
      variants={containerVariants}
      initial="hidden"
      animate="visible"
    >
      <motion.div className="hero-content" variants={itemVariants}>
        <motion.h1 variants={itemVariants}>
          Mallikarjun <br /> Bendawade.
        </motion.h1>

        <motion.h2 variants={itemVariants} className="hero-tagline">
          Building intelligent solutions with AI & modern development.
        </motion.h2>

        <motion.p variants={itemVariants} className="hero-subtitle">
          I'm a Software Developer & AI Enthusiast from Bengaluru, focused on
          creating elegant solutions to complex problems. Specializing in AI,
          Web Development, and scalable backend systems.
        </motion.p>

        <motion.div className="hero-cta" variants={itemVariants}>
          <motion.a href="#projects" className="btn btn-primary">
            View My Work
          </motion.a>
          <motion.a href="#contact" className="btn btn-secondary">
            Get in Touch
          </motion.a>
        </motion.div>
      </motion.div>

      <motion.div className="hero-scroll" variants={itemVariants}>
        <span>Scroll to explore</span>
        <motion.div
          className="scroll-indicator"
          animate={{ y: [0, 10, 0] }}
          transition={{ duration: 2, repeat: Infinity }}
        >
          ↓
        </motion.div>
      </motion.div>
    </motion.section>
  );
};

export default Hero;
